<?php
namespace App\Domain\AI\Launchpad\Data;
use App\Domain\AI\Agents\Data\{AgentConfigurationData,AgentContractDraftData};
use App\Domain\AI\Agents\Enums\AgentType;
use App\Domain\AI\Support\StructuredDataGuard;
use InvalidArgumentException;
final readonly class LaunchpadRecommendationData
{
    public function __construct(public AgentType $recommendedAgentType,public string $suggestedName,public string $jobToBeDone,public array $objectives,public array $allowedCapabilities,public array $prohibitedCapabilities,public array $channels,public array $knowledgeRequirements,public array $allowedActions,public array $handoffPolicy,public array $outcomePolicy,public array $capacityPolicy,public array $slaPolicy,public array $privacyPolicy,public array $pricingPolicy,public array $agentConfiguration,public string $explanation,public array $assumptions,public array $missingInformation,public array $riskFlags,public array $alternatives,public string $confidence,public string $advisorCode,public string $schemaVersion)
    {if(!in_array($confidence,['high','medium','low'],true)||trim($suggestedName)===''||trim($explanation)===''||trim($advisorCode)===''||trim($schemaVersion)==='')throw new InvalidArgumentException('Recommendation metadata is invalid.');$this->contract();$this->configuration();StructuredDataGuard::validate($this->toArray());}
    public function contract():AgentContractDraftData{return new AgentContractDraftData($this->jobToBeDone,$this->objectives,$this->allowedCapabilities,$this->prohibitedCapabilities,$this->channels,$this->knowledgeRequirements,$this->allowedActions,$this->handoffPolicy,$this->outcomePolicy,$this->capacityPolicy,$this->slaPolicy,$this->privacyPolicy,$this->pricingPolicy);}
    public function configuration():AgentConfigurationData{return new AgentConfigurationData($this->schemaVersion,$this->agentConfiguration);}
    public function toArray():array{return['recommended_agent_type'=>$this->recommendedAgentType->value,'suggested_name'=>$this->suggestedName,'job_to_be_done'=>$this->jobToBeDone,'objectives'=>$this->objectives,'allowed_capabilities'=>$this->allowedCapabilities,'prohibited_capabilities'=>$this->prohibitedCapabilities,'channels'=>$this->channels,'knowledge_requirements'=>$this->knowledgeRequirements,'allowed_actions'=>$this->allowedActions,'handoff_policy'=>$this->handoffPolicy,'outcome_policy'=>$this->outcomePolicy,'capacity_policy'=>$this->capacityPolicy,'sla_policy'=>$this->slaPolicy,'privacy_policy'=>$this->privacyPolicy,'pricing_policy'=>$this->pricingPolicy,'agent_configuration'=>$this->agentConfiguration,'explanation'=>$this->explanation,'assumptions'=>$this->assumptions,'missing_information'=>$this->missingInformation,'risk_flags'=>$this->riskFlags,'alternatives'=>$this->alternatives,'confidence'=>$this->confidence,'advisor_code'=>$this->advisorCode,'schema_version'=>$this->schemaVersion];}
    public static function fromArray(array $d):self{foreach(['recommended_agent_type','suggested_name','job_to_be_done','objectives','allowed_capabilities','prohibited_capabilities','channels','knowledge_requirements','allowed_actions','handoff_policy','outcome_policy','capacity_policy','sla_policy','privacy_policy','pricing_policy','agent_configuration','explanation','assumptions','missing_information','risk_flags','alternatives','confidence','advisor_code','schema_version']as$k)if(!array_key_exists($k,$d))throw new InvalidArgumentException('Stored recommendation is incomplete.');return new self(AgentType::from($d['recommended_agent_type']),$d['suggested_name'],$d['job_to_be_done'],$d['objectives'],$d['allowed_capabilities'],$d['prohibited_capabilities'],$d['channels'],$d['knowledge_requirements'],$d['allowed_actions'],$d['handoff_policy'],$d['outcome_policy'],$d['capacity_policy'],$d['sla_policy'],$d['privacy_policy'],$d['pricing_policy'],$d['agent_configuration'],$d['explanation'],$d['assumptions'],$d['missing_information'],$d['risk_flags'],$d['alternatives'],$d['confidence'],$d['advisor_code'],$d['schema_version']);}
}
